ee:message.ee:set-payload:
%dw 2.0
output application/json
var orderKeys = payload filter ($ startsWith (vars.vLedgerOrderId ++ "|"))
---
{
	orderId: vars.vLedgerOrderId,
	charges: sizeOf(orderKeys filter ($ contains "|charge|")),
	duplicatesRejected: sizeOf(orderKeys filter ($ contains "|duplicate|"))
}
